const items     = $input.all();
const endMs     = Date.now();
const startMs   = $('Record Start Time').item.json.start_time_ms;
const inputTok  = $('Record Start Time').item.json.input_token_estimate;
const inputText = $('Record Start Time').item.json.input_text;
const latMs     = endMs - startMs;
const latSec    = parseFloat((latMs / 1000).toFixed(2));

// ── Deterministic scoring (no extra LLM call) ─────────────────────────────
function scoreAnswer(text) {
  if (!text || text.trim().length === 0) return { total: 0, breakdown: {} };
  const t         = text.trim();
  const words     = t.split(/\s+/);
  const wc        = words.length;
  const sentences = (t.match(/[.!?]+(\s|$)/g) || []).length;
  const uniqueWords = new Set(words.map(w => w.toLowerCase().replace(/[^a-z]/g, '')));
  const ttr       = uniqueWords.size / Math.max(wc, 1);

  const lengthScore   = wc >= 80 && wc <= 220 ? 3 : wc >= 50 ? 1 : 0;
  const sentenceScore = sentences >= 4 ? 3 : sentences >= 3 ? 2 : sentences >= 2 ? 1 : 0;
  const toneScore     = (!t.startsWith('I ') && wc > 40) ? 2 : 0;
  const uniqueScore   = ttr >= 0.6 ? 2 : ttr >= 0.5 ? 1 : 0;
  return { total: lengthScore + sentenceScore + toneScore + uniqueScore,
           breakdown: { lengthScore, sentenceScore, toneScore, uniqueScore } };
}

// ── Parse each agent output ───────────────────────────────────────────────
const agentLabels = [
  'Vote Agent 1 (Run 1 of 3)',
  'Vote Agent 2 (Run 2 of 3)',
  'Vote Agent 3 (Run 3 of 3)'
];

const agents = items.map((item, i) => {
  const text    = (item.json.text || item.json.output || '').trim();
  const words   = text ? text.split(/\s+/).length : 0;
  const tokEst  = Math.ceil(text.length / 4);
  const scored  = scoreAnswer(text);
  return {
    label:           agentLabels[i] || `Vote Agent ${i + 1}`,
    run:             i + 1,
    text:            text,
    word_count:      words,
    tokens:          tokEst,
    quality_score:   scored.total,
    score_breakdown: scored.breakdown,
    produced:        text.length > 0
  };
});

// ── Select winner ─────────────────────────────────────────────────────────
const ranked   = [...agents].sort((a, b) =>
  b.quality_score !== a.quality_score
    ? b.quality_score - a.quality_score
    : b.word_count - a.word_count
);
const winner   = ranked[0];
const scores   = agents.map(a => a.quality_score);
const maxScore = Math.max(...scores);
const minScore = Math.min(...scores);
const spread   = maxScore - minScore;
const tieUsed  = scores.filter(s => s === maxScore).length > 1;

// ── Token totals ──────────────────────────────────────────────────────────
const totalOutputTok = agents.reduce((s, a) => s + a.tokens, 0);
const totalTok       = inputTok + totalOutputTok;

// ── Spread label ──────────────────────────────────────────────────────────
const spreadLabel = spread === 0 ? 'UNANIMOUS - all agents scored equally'
                  : spread <= 2  ? 'LOW - high agreement between agents'
                  : spread <= 4  ? 'MEDIUM - moderate divergence'
                  :                'HIGH - agents diverged significantly';

// ── Standard envelope ─────────────────────────────────────────────────────
return [{
  json: {
    user_prompt:  inputText,
    final_answer: winner.text,
    metadata: {
      pattern:          'Parallel Voting',
      pattern_category: 'Parallel Decomposition Pattern',
      run_timestamp:    new Date().toISOString(),
      model:            'qwen2.5:14b',
      model_provider:   'Ollama (local)',
      temperature:      0.7,
      latency_ms:       latMs,
      latency_seconds:  latSec,
      llm_calls_actual: 3,
      llm_calls_max:    3,
      token_usage: {
        total_input_tokens:  inputTok,
        total_output_tokens: totalOutputTok,
        total_tokens:        totalTok
      },
      status:            'completed',
      termination_reason: 'all_votes_collected_winner_selected'
    },
    execution_trace: {
      vote_agents: {
        vote_1: {
          label:           agents[0].label,
          output:          agents[0].text,
          tokens:          agents[0].tokens,
          word_count:      agents[0].word_count,
          quality_score:   agents[0].quality_score,
          score_breakdown: agents[0].score_breakdown,
          is_winner:       agents[0].label === winner.label
        },
        vote_2: {
          label:           agents[1].label,
          output:          agents[1].text,
          tokens:          agents[1].tokens,
          word_count:      agents[1].word_count,
          quality_score:   agents[1].quality_score,
          score_breakdown: agents[1].score_breakdown,
          is_winner:       agents[1].label === winner.label
        },
        vote_3: {
          label:           agents[2].label,
          output:          agents[2].text,
          tokens:          agents[2].tokens,
          word_count:      agents[2].word_count,
          quality_score:   agents[2].quality_score,
          score_breakdown: agents[2].score_breakdown,
          is_winner:       agents[2].label === winner.label
        }
      },
      voting_decision: {
        winner_agent:         winner.label,
        winner_run:           winner.run,
        winner_quality_score: winner.quality_score,
        score_spread:         spread,
        score_spread_label:   spreadLabel,
        all_scores:           agents.map(a => ({ agent: a.label, score: a.quality_score })),
        selection_method:     'deterministic scoring (length + sentences + tone + lexical diversity) - zero extra LLM cost',
        tie_break_used:       tieUsed
      },
      pipeline_integrity: {
        all_agents_completed: agents.every(a => a.produced),
        agents_completed:     agents.filter(a => a.produced).length,
        agents_failed:        agents.filter(a => !a.produced).length,
        merge_waited_for_all: true
      },
      structural_properties: {
        orchestration_type:        'parallel_fanout_then_vote',
        vote_agents_count:         3,
        vote_agents_run_in_parallel: true,
        aggregation_strategy:      'deterministic quality scoring (code node - zero extra LLM call)',
        merger_type:               'n8n_merge_node_3_inputs',
        llm_calls_for_aggregation: 0
      }
    }
  }
}];
